from lib import *
S = SS('x6')
steps = [
    step("setter / 字段注入的循环(纯 Spring)。时间线:构造 A,构造 B(为了给 A 注入),B.setA 拿到的 A 还没初始化完成(早期引用),B 的 @PostConstruct 先于 A 的执行,此时 A.ready=false;随后 A.setB 时 B 已经初始化完成,最后 A 的 @PostConstruct。结果 a.b == b、b.a == a 都是 true。循环依赖能解开,但 B 在初始化时看到的 A 是半成品。", t=tl(S(1)), mark=lidx(S(1), 'B.setA(拿到的 A 还没初始化完成)', 'B.@PostConstruct(此时 A.ready=false)'), done=lidx(S(1), '构造 A', '构造 B', 'A.@PostConstruct', 'a.b == b'), b=bars([['时间线上的事件数', 6, '6'], ['B 初始化时 A.ready', 0, 'false(半成品)'], ['A.b 是同一个 B', 1, 'true'], ['B.a 是同一个 A', 1, 'true']], 6, cur=[0], mark=[1], done=[2, 3]), kv=KV([['创建顺序', 'A → B → B 初始化 → A 初始化'], ['B 看到的 A', '还没初始化完成'], ['结果', '互相持有同一个对象'], ['机制', '早期引用(三级缓存)']], ['B 看到的 A'])),
    step("构造器注入的循环(纯 Spring):BeanCurrentlyInCreationException:Error creating bean with name 'ca': Requested bean is currently in creation: Is there an unresolvable circular reference or an asynchronous initialization dependency?。构造器参数需要对方已经存在,但对方也在等自己,没有半成品可以提前拿。", t=tl(S(2)), mark=lidx(S(2), 'ctor → BeanCurrentlyInCreationException'), b=bars([['构造器循环能启动', 0, '不能'], ['setter 循环能启动(纯 Spring)', 1, '能']], 1, mark=[0], done=[1]), kv=KV([['异常', 'BeanCurrentlyInCreationException'], ['消息', 'Requested bean is currently in creation'], ['原因', '构造器参数没有半成品可用'], ['对比', 'setter 循环可以']], ['原因'])),
    step("SpringApplication 对 setter 循环的态度。allowCircularReferences=false(默认)启动失败:BeanCurrentlyInCreationException:Error creating bean with name 'a':Requested bean is currently in creation。把 allowCircularReferences 设成 true:启动成功。纯 Spring 默认允许,SpringApplication 默认关掉了。", t=tl(S(3)), mark=lidx(S(3), 'allowCircularReferences=false'), done=lidx(S(3), 'allowCircularReferences=true'), b=bars([['allowCircularReferences=false 启动', 0, '失败'], ['allowCircularReferences=true 启动', 1, '成功']], 1, mark=[0], done=[1]), kv=KV([['SpringApplication 默认', '禁止循环引用'], ['打开', 'setAllowCircularReferences(true)'], ['纯 Spring', '默认允许'], ['异常', 'BeanCurrentlyInCreationException']], ['SpringApplication 默认'])),
    step("循环依赖加一个只实现 BeanPostProcessor 的包装器(在 postProcessAfterInitialization 里把 SA 换成 JDK 代理)。记忆里的老版本会抛 “injected into other beans in its raw version ... but has eventually been wrapped”,这次没有在老版本上验证。Spring 7.0.9 启动成功:时间线显示 SA 和 SB 各被构造了 2 次。第一轮 SB 拿到的是 SA 的原始对象,发现 SA 之后被包装,于是第二轮重新构造 SB、SA,这回 SB 注入的是代理。最终 SB 持有的 sa 是代理,与容器里的 sa 是同一个对象。isAllowRawInjectionDespiteWrapping 仍是 false。", t=tl(S(4)), mark=lidx(S(4), '构造 SA 的次数', '5. 构造 SB'), done=lidx(S(4), 'SB 注入 sa:代理', '启动成功'), b=bars([['构造 SA 的次数', 2, '2'], ['构造 SB 的次数', 2, '2'], ['SB 最终持有代理', 1, '是'], ['SB 第一轮持有原始对象', 1, '是(被丢弃)']], 2, cur=[0, 1], done=[2], mark=[3]), kv=KV([['SA、SB', '各构造 2 次'], ['第一轮', 'SB 拿到 SA 的原始对象'], ['第二轮', 'SB 拿到代理'], ['最终', '容器里的 sa 与 SB 持有的是同一个代理']], ['SA、SB'])),
    step("循环依赖加 Spring AOP(@Aspect 环绕通知 PA.hello,PA 与 PB 互相依赖)。容器里的 PA 是代理,PB 持有的 pa 也是代理,pb.pa.hello() 返回 [切面]PA.hello,pb.pa 就是容器里的 PA。自动代理创建器能在循环时提前暴露代理,所以 B 拿到的就是代理,切面对循环里的调用也生效。", t=tl(S(5)), mark=lidx(S(5), '容器里的 PA 是代理?true'), b=bars([['容器里的 PA 是代理', 1, 'true'], ['PB 持有的 pa 是代理', 1, 'true'], ['pb.pa 就是容器里的 PA', 1, 'true']], 1, done=[0, 1, 2]), kv=KV([['容器里的 PA', '代理'], ['PB 持有的 pa', '同一个代理'], ['pb.pa.hello()', '[切面]PA.hello'], ['机制', '自动代理创建器提前暴露代理']], ['PB 持有的 pa'])),
    step("用 @Lazy 打破构造器循环。LA 的构造器参数 LB 和 la 的 @Bean 方法参数都标了 @Lazy:构造 LA 时拿到的 LB 是懒加载代理,于是先构造 LA,再构造 LB(LB 的构造器能拿到完整的 LA)。构造器循环不再失败。", t=tl(S(6)), mark=lidx(S(6), '构造 LA(拿到的 LB 是一个懒加载代理)'), done=lidx(S(6), '构造 LB'), b=bars([['LA 拿到的 LB', 1, '懒加载代理'], ['构造器循环能启动', 1, '能']], 1, cur=[0], done=[1]), kv=KV([['@Lazy 参数', '注入一个代理,用到时才解析'], ['LA', '先构造'], ['LB', '后构造,拿到完整的 LA'], ['循环', '依赖关系仍在,只是延迟']], ['@Lazy 参数'])),
]
